begin;set search_path to public,extensions;select plan(13);
insert into auth.users(id,email) values('30000000-0000-4000-8000-000000000001','contribution-a@example.test'),('30000000-0000-4000-8000-000000000002','contribution-b@example.test');
set local role anon;
select throws_ok($$select public.get_saved_properties()$$,'42501',null,'Anonymous shortlist denied');
select throws_ok($$select public.create_property('{}',false)$$,'42501',null,'Anonymous contribution denied');
set local role authenticated;select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.set_saved_property('20000000-0000-4000-8000-000000000001',true)$$,'Save succeeds');
select lives_ok($$select public.set_saved_property('20000000-0000-4000-8000-000000000001',true)$$,'Repeated save idempotent');
select is((select count(*)::int from public.get_saved_properties()),1,'One saved row');
select throws_ok($$select * from private.saved_properties$$,'42501',null,'Direct private shortlist denied');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.get_saved_properties()),0,'Other account cannot read first shortlist');
select lives_ok($$select public.set_saved_property('20000000-0000-4000-8000-000000000001',false)$$,'Other account remove does not affect first');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000001',true);
select is((select count(*)::int from public.get_saved_properties()),1,'First account save survives other remove');
select ok((select exact from public.find_property_duplicates('Delhi','New Delhi',' Demo Lane 12, Central Park ','Different name') limit 1),'Exact city-qualified address detected');
select ok(not exists(select 1 from public.find_property_duplicates('Rajasthan','Jaipur','Demo Lane 12, Central Park','Demo Neem Courtyard') where id='20000000-0000-4000-8000-000000000001'),'Candidate matching never crosses city/state boundaries');
select throws_ok($$select public.create_property('{"synthetic":false}',false)$$,'P0001',null,'Non-synthetic input denied');
select throws_ok($$select public.create_property('{"synthetic":true,"state":"Delhi","city":"New Delhi","address":"demo lane 12 central park","name":"Copy"}',true)$$,'P0001',null,'Exact duplicate denied even with acknowledgment');
select * from finish();rollback;
